CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, email VARCHAR(50) NOT NULL, password_hash VARCHAR(128) NOT NULL, CONSTRAINT chk_Users_unsigned_integer_id CHECK (id BETWEEN 0 AND 4294967295));
ALTER TABLE users ADD CONSTRAINT users_email_unique UNIQUE (email);
CREATE SEQUENCE IF NOT EXISTS Users_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;